 "content": "from collections import Counter


def transform(grid):
    """Downsample 3x3 tiles, retaining any foreground color (not 0 or 5)."""
    h, w = len(grid), len(grid[0])
    out = []
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            colors = Counter(
                grid[i][j]
                for i in range(r, min(r + 3, h))
                for j in range(c, min(c + 3, w))
                if grid[i][j] not in (0, 5)
            )
            row.append(colors.most_common(1)[0][0] if colors else 0)
        out.append(row)
    return out
